// Renders KKL_Technical_Documentation.md (itself generated by
// build-consolidated.mjs) as a Word document for readers who want one file
// rather than a repository. Nothing here is a source of truth: edit a chapter,
// re-run build-consolidated.mjs, then re-run this.
//
//   npm install docx        # not a dependency of the application
//   node docs/technical-history/md2docx.mjs
//
// The seven Mermaid fences are replaced by the pre-rendered PNGs in
// ./diagrams, which were produced with @mermaid-js/mermaid-cli:
//
//   mmdc -i diagram-N.mmd -o diagram-N.png -b white -s 2
//
// A fence with no matching PNG falls back to its Mermaid source as a code
// block, so the document still builds without the renderer.

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import {
  AlignmentType, BorderStyle, Bookmark, Document, ExternalHyperlink, Footer,
  HeadingLevel, ImageRun, InternalHyperlink, LevelFormat, LineRuleType, PageBreak,
  PageNumber, PageOrientation, Packer, Paragraph, ShadingType, Table,
  TableCell, TableRow, TextRun, VerticalAlign, WidthType,
} from "docx";

const here = dirname(fileURLToPath(import.meta.url));
const SRC = join(here, "KKL_Technical_Documentation.md");
const OUT = process.argv[2] ?? join(here, "KKL_Technical_Documentation.docx");

const INK = "1F2937";
const MUTED = "5B6478";
const RULE = "D5D9E3";
const CODE_BG = "F4F5F8";
const HEAD_BG = "E8ECF4";
const LINK = "1D4ED8";

const PORTRAIT_W = 9026;   // A4 minus 1" margins, in DXA
const LANDSCAPE_W = 14966;  // landscape A4 with narrower side margins

const px = (n) => Math.round(n);

// ---------------------------------------------------------------- inline ---

const slugCounts = new Map();
const slugOf = (text) => {
  const base = text
    .replace(/`/g, "")
    .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
    .replace(/\*\*/g, "")
    .toLowerCase()
    .replace(/[^\w\- ]+/g, "")
    .trim()
    .replace(/ +/g, "-");
  const n = slugCounts.get(base) ?? 0;
  slugCounts.set(base, n + 1);
  return n === 0 ? base : `${base}-${n}`;
};

const bookmarks = new Map(); // anchor -> Word bookmark id
let bookmarkSeq = 0;
const bookmarkFor = (anchor) => {
  if (!bookmarks.has(anchor)) {
    bookmarkSeq += 1;
    bookmarks.set(anchor, `_Ref${String(bookmarkSeq).padStart(4, "0")}`);
  }
  return bookmarks.get(anchor);
};

/** Markdown inline -> docx runs. Links are matched first, because a link
 *  label may itself contain a code span; code spans are taken out next, so
 *  emphasis markers inside them are never interpreted. */
function runs(text, base = {}) {
  const out = [];
  const link = /\[([^\]]+)\]\(([^)\s]+)\)/g;
  let last = 0;
  let m;
  while ((m = link.exec(text)) !== null) {
    if (m.index > last) out.push(...plain(text.slice(last, m.index), base));
    const children = plain(m[1], { ...base, color: LINK, underline: {} });
    out.push(
      m[2].startsWith("#")
        ? new InternalHyperlink({ anchor: bookmarkFor(m[2].slice(1)), children })
        : new ExternalHyperlink({ link: m[2], children }),
    );
    last = link.lastIndex;
  }
  if (last < text.length) out.push(...plain(text.slice(last), base));
  return out;
}

/** Everything except links: code spans, bold and italic, in one pass so that
 *  bold wrapping a code span (**`kkl-web`**) survives, while emphasis markers
 *  inside a code span stay literal. A lone ** — a glob such as src/app/** —
 *  only becomes bold if a closing ** follows and the content starts with a
 *  word character, so path globs are left alone. */
function plain(text, base = {}) {
  const out = [];
  const token = /(`[^`]+`)|\*\*([^\s;,)][^\n]*?)\*\*|(?<![*\w])\*([^*\n]+)\*(?!\*)/g;
  let last = 0;
  let m;
  while ((m = token.exec(text)) !== null) {
    if (m.index > last) out.push(new TextRun({ ...base, text: text.slice(last, m.index) }));
    if (m[1] !== undefined) {
      out.push(new TextRun({
        ...base, text: m[1].slice(1, -1), font: "Consolas", size: 18,
        shading: { type: ShadingType.CLEAR, fill: CODE_BG },
      }));
    } else if (m[2] !== undefined) {
      out.push(...plain(m[2], { ...base, bold: true }));
    } else {
      out.push(...plain(m[3], { ...base, italics: true }));
    }
    last = token.lastIndex;
  }
  if (last < text.length) out.push(new TextRun({ ...base, text: text.slice(last) }));
  return out;
}

// ------------------------------------------------------------------ parse ---

const lines = readFileSync(SRC, "utf8").split("\n");

// Pass 1: heading anchors in document order, so links resolve to the same
// anchors the Markdown version uses.
{
  let fence = false;
  for (const line of lines) {
    if (/^\s*(```|~~~)/.test(line)) { fence = !fence; continue; }
    if (fence) continue;
    const m = /^(#{1,6}) +(.*?)\s*$/.exec(line);
    if (m) bookmarkFor(slugOf(m[2]));
  }
  slugCounts.clear();
}

const HEADING = {
  1: HeadingLevel.HEADING_1,
  2: HeadingLevel.HEADING_1,
  3: HeadingLevel.HEADING_2,
  4: HeadingLevel.HEADING_3,
  5: HeadingLevel.HEADING_4,
  6: HeadingLevel.HEADING_4,
};

const portrait = [];
const landscape = [];
let sink = portrait;
let diagram = 0;

const emit = (el) => sink.push(el);
const endList = () => { lastWasOrdered = false; };

const spacer = (after = 120) =>
  new Paragraph({ spacing: { after }, children: [] });

function codeParagraphs(body) {
  return body.map((line, i) =>
    new Paragraph({
      keepLines: true,
      keepNext: i < body.length - 1,
      spacing: { before: i === 0 ? 80 : 0, after: i === body.length - 1 ? 160 : 0, line: 240 },
      shading: { type: ShadingType.CLEAR, fill: CODE_BG },
      indent: { left: 170, right: 170 },
      children: [new TextRun({ text: line || " ", font: "Consolas", size: 17, color: INK })],
    }),
  );
}

function pngSize(buffer) {
  return { width: buffer.readUInt32BE(16), height: buffer.readUInt32BE(20) };
}

function diagramImage(source) {
  diagram += 1;
  const file = join(here, "diagrams", `diagram-${diagram}.png`);
  if (!existsSync(file)) return codeParagraphs(source);
  const data = readFileSync(file);
  const { width, height } = pngSize(data);
  const maxW = 600;  // points at 96dpi across an A4 text column
  const maxH = 720;
  let w = width / 2;   // rendered at scale 2
  let h = height / 2;
  const fit = Math.min(maxW / w, maxH / h, 1);
  w *= fit; h *= fit;
  // A tall diagram gets its own page: a figure that does not fit the space
  // left on the current one is clipped by some renderers rather than moved.
  const ownPage = h > 360;
  return [
    new Paragraph({
      alignment: AlignmentType.CENTER,
      pageBreakBefore: ownPage,
      // The document's default line height would crop an inline image to one
      // line, so the figure paragraph sets its own automatic line rule.
      spacing: { before: 160, after: 200, line: 240, lineRule: LineRuleType.AUTO },
      children: [new ImageRun({ data, type: "png", transformation: { width: px(w), height: px(h) } })],
    }),
  ];
}

function splitRow(line) {
  return line.replace(/^\|/, "").replace(/\|\s*$/, "").split(/(?<!\\)\|/)
    .map((c) => c.replace(/\\\|/g, "|").trim());
}

function table(rows, width) {
  const header = rows[0];
  const body = rows.slice(2);
  const cols = header.length;
  const column = (i) => [header[i], ...body.map((r) => r[i] ?? "")];

  // A column must be wide enough for its longest unbreakable run, or Word
  // splits words mid-letter; beyond that, width follows how much text the
  // column actually carries.
  const CHAR = 104;     // DXA per character at 8.5pt Calibri, with headroom
  const PADDING = 260;  // cell margins plus borders
  const longestToken = (i) =>
    Math.max(...column(i).map((c) =>
      Math.max(0, ...c.replace(/[`*]/g, "").split(/[\s/;,]+/).map((w) => w.length))));
  const minima = header.map((_, i) =>
    Math.min(Math.max(longestToken(i) * CHAR + PADDING, 760), 1900));
  const weights = header.map((_, i) => {
    const cells = column(i);
    const avg = cells.reduce((a, c) => a + c.length, 0) / cells.length;
    return Math.sqrt(Math.max(avg, 3));
  });

  let widths;
  const floor = minima.reduce((a, b) => a + b, 0);
  if (floor >= width) {
    const scale = width / floor;
    widths = minima.map((m) => Math.floor(m * scale));
  } else {
    const spare = width - floor;
    const total = weights.reduce((a, b) => a + b, 0);
    widths = minima.map((m, i) => m + Math.floor((weights[i] / total) * spare));
  }
  const drift = width - widths.reduce((a, b) => a + b, 0);
  widths[widths.indexOf(Math.max(...widths))] += drift;

  const border = { style: BorderStyle.SINGLE, size: 2, color: RULE };
  const cell = (text, i, isHeader) =>
    new TableCell({
      width: { size: widths[i], type: WidthType.DXA },
      margins: { top: 70, bottom: 70, left: 110, right: 110 },
      verticalAlign: VerticalAlign.TOP,
      shading: isHeader ? { type: ShadingType.CLEAR, fill: HEAD_BG } : undefined,
      children: [
        new Paragraph({
          spacing: { before: 0, after: 0, line: 230 },
          children: runs(text === "—" ? "—" : text, { size: 17, bold: isHeader || undefined }),
        }),
      ],
    });

  return new Table({
    columnWidths: widths,
    width: { size: width, type: WidthType.DXA },
    borders: { top: border, bottom: border, left: border, right: border,
      insideHorizontal: border, insideVertical: border },
    rows: [
      new TableRow({
        tableHeader: true,
        cantSplit: true,
        children: header.map((c, i) => cell(c, i, true)),
      }),
      ...body.map((r) =>
        new TableRow({
          cantSplit: true,
          children: Array.from({ length: cols }, (_, i) => cell(r[i] ?? "", i, false)),
        }),
      ),
    ],
  });
}

let i = 0;
let pendingBreak = false;
const bulletRef = "kkl-bullet";
// Each ordered list needs its own numbering instance, or Word continues the
// previous list's count instead of starting again at 1.
const orderedRefs = [];
let orderedRef = null;
let lastWasOrdered = false;

while (i < lines.length) {
  const line = lines[i];

  // fenced block
  const fence = /^\s*(```|~~~)(\w*)\s*$/.exec(line);
  if (fence) {
    const lang = fence[2];
    const body = [];
    i += 1;
    while (i < lines.length && !/^\s*(```|~~~)\s*$/.test(lines[i])) { body.push(lines[i]); i += 1; }
    i += 1;
    endList();
    (lang === "mermaid" ? diagramImage(body) : codeParagraphs(body)).forEach(emit);
    continue;
  }

  // table
  if (line.startsWith("|") && (lines[i + 1] ?? "").startsWith("|") && /^\|[\s:|-]+\|?\s*$/.test(lines[i + 1])) {
    const rows = [];
    while (i < lines.length && lines[i].startsWith("|")) { rows.push(splitRow(lines[i])); i += 1; }
    endList();
    emit(table(rows, sink === landscape ? LANDSCAPE_W : PORTRAIT_W));
    emit(spacer(200));
    continue;
  }

  // heading
  const head = /^(#{1,6}) +(.*?)\s*$/.exec(line);
  if (head) {
    const level = head[1].length;
    const text = head[2];
    const anchor = slugOf(text);
    if (level === 1) { i += 1; continue; } // document title lives on the cover

    if (text.startsWith("Appendix A")) {
      sink = landscape;
      pendingBreak = false;
    }

    endList();
    const children = [
      new Bookmark({ id: bookmarkFor(anchor), children: runs(text, {}) }),
    ];
    emit(new Paragraph({
      heading: HEADING[level],
      pageBreakBefore: pendingBreak && level === 2,
      keepNext: true,
      children,
    }));
    pendingBreak = false;
    i += 1;
    continue;
  }

  // horizontal rule: a chapter divider becomes a page break, anything else a rule
  if (/^-{3,}$/.test(line.trim())) {
    let j = i + 1;
    while (j < lines.length && lines[j].trim() === "") j += 1;
    if (/^## /.test(lines[j] ?? "")) pendingBreak = true;
    else emit(new Paragraph({
      spacing: { before: 120, after: 160 },
      border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: RULE, space: 4 } },
      children: [],
    }));
    i += 1;
    continue;
  }

  // blockquote
  if (/^> ?/.test(line)) {
    const body = [];
    while (i < lines.length && /^> ?/.test(lines[i])) { body.push(lines[i].replace(/^> ?/, "")); i += 1; }
    const paragraphs = body.join("\n").split(/\n{2,}/);
    paragraphs.forEach((p, n) => emit(new Paragraph({
      spacing: { before: n === 0 ? 120 : 60, after: n === paragraphs.length - 1 ? 180 : 60, line: 280 },
      indent: { left: 340 },
      border: { left: { style: BorderStyle.SINGLE, size: 12, color: "9AA6C0", space: 10 } },
      children: runs(p.replace(/\n/g, " "), { color: "3A4358" }),
    })));
    continue;
  }

  // list item (one level of nesting)
  const item = /^(\s*)([-*]|\d+\.) +(.*)$/.exec(line);
  if (item) {
    const indent = item[1].length;
    const ordered = /\d/.test(item[2]);
    let text = item[3];
    i += 1;
    while (i < lines.length && /^\s{2,}\S/.test(lines[i]) && !/^(\s*)([-*]|\d+\.) +/.test(lines[i])) {
      text += ` ${lines[i].trim()}`;
      i += 1;
    }
    if (ordered && !lastWasOrdered) {
      orderedRef = `kkl-number-${orderedRefs.length + 1}`;
      orderedRefs.push(orderedRef);
    }
    lastWasOrdered = ordered;
    emit(new Paragraph({
      numbering: { reference: ordered ? orderedRef : bulletRef, level: indent >= 2 ? 1 : 0 },
      spacing: { before: 40, after: 40, line: 280 },
      children: runs(text),
    }));
    continue;
  }

  // blank
  if (line.trim() === "") { i += 1; continue; }

  // paragraph
  const body = [];
  while (i < lines.length && lines[i].trim() !== ""
    && !/^(#{1,6}) /.test(lines[i]) && !lines[i].startsWith("|")
    && !/^\s*(```|~~~)/.test(lines[i]) && !/^> ?/.test(lines[i])
    && !/^(\s*)([-*]|\d+\.) +/.test(lines[i]) && !/^-{3,}$/.test(lines[i].trim())) {
    body.push(lines[i].trim());
    i += 1;
  }
  endList();
  emit(new Paragraph({
    spacing: { before: 60, after: 140, line: 290 },
    children: runs(body.join(" ")),
  }));
}

// ------------------------------------------------------------------ cover ---

const coverLine = (text, opts = {}) =>
  new Paragraph({
    alignment: AlignmentType.LEFT,
    spacing: { before: opts.before ?? 0, after: opts.after ?? 120, line: 300 },
    children: runs(text, opts.run ?? {}),
  });

const cover = [
  new Paragraph({ spacing: { before: 1800, after: 0 }, children: [
    new TextRun({ text: "Kam Ki Lead", size: 56, bold: true, color: INK }),
  ] }),
  new Paragraph({ spacing: { before: 60, after: 400 }, children: [
    new TextRun({ text: "Consolidated technical documentation", size: 34, color: MUTED }),
  ] }),
  new Paragraph({
    spacing: { after: 320 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: RULE, space: 6 } },
    children: [],
  }),
  coverLine("**Prepared** 28 September 2026"),
  coverLine("**Scope** The original demo, Phase 1, Phase 2 and the client-review changes CR01–CR07"),
  coverLine("**Source** `docs/technical-history/` on branch `claude/phase-2-frontend` of `Kam-Ki-Lead/kkl-web`"),
  coverLine("**Repositories documented** kkl-web `36114f5` · kkl-backend `bc8ab30` · kkl-design `5bc3512` · kkl-voice `349bd16` · bdrpl-application `8e144e9`"),
  new Paragraph({
    spacing: { before: 400, after: 0, line: 300 },
    shading: { type: ShadingType.CLEAR, fill: CODE_BG },
    indent: { left: 200, right: 200 },
    border: { left: { style: BorderStyle.SINGLE, size: 12, color: "9AA6C0", space: 10 } },
    children: runs(
      "This document records work performed. **It is not an acceptance record.** " +
      "No client approval is inferred from a commit, a passing suite or a filled-in template anywhere in it. " +
      "No test was re-run to produce it: every result is attributed to the commit it was measured at.",
      { size: 19, color: "3A4358" },
    ),
  }),
  new Paragraph({ spacing: { before: 200 }, children: [
    new TextRun({ text: "Generated from the Markdown chapters in docs/technical-history/, so this document and the repository copy cannot diverge.", size: 17, color: MUTED, italics: true }),
  ] }),
  new Paragraph({ children: [new PageBreak()] }),
];

const footer = (label) => new Footer({
  children: [new Paragraph({
    alignment: AlignmentType.RIGHT,
    spacing: { before: 120 },
    border: { top: { style: BorderStyle.SINGLE, size: 4, color: RULE, space: 6 } },
    children: [
      new TextRun({ text: `${label}   `, size: 16, color: MUTED }),
      new TextRun({ children: [PageNumber.CURRENT], size: 16, color: MUTED }),
      new TextRun({ text: " of ", size: 16, color: MUTED }),
      new TextRun({ children: [PageNumber.TOTAL_PAGES], size: 16, color: MUTED }),
    ],
  })],
});

const heading = (size, before, after) => ({
  run: { size, bold: true, color: INK, font: "Calibri" },
  paragraph: { spacing: { before, after }, keepNext: true },
});

const doc = new Document({
  title: "Kam Ki Lead — consolidated technical documentation",
  description: "Prompt-by-prompt technical history of the Kam Ki Lead project",
  creator: "Kam Ki Lead project",
  styles: {
    default: {
      document: {
        run: { font: "Calibri", size: 21, color: INK },
        paragraph: { spacing: { line: 290 } },
      },
      heading1: heading(30, 360, 160),
      heading2: heading(24, 280, 120),
      heading3: heading(21, 240, 100),
      heading4: heading(20, 200, 80),
    },
    paragraphStyles: [
      { id: "Hyperlink", name: "Hyperlink", run: { color: LINK, underline: {} } },
    ],
  },
  numbering: {
    config: [
      {
        reference: bulletRef,
        levels: [
          { level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT,
            style: { paragraph: { indent: { left: 360, hanging: 200 } } } },
          { level: 1, format: LevelFormat.BULLET, text: "◦", alignment: AlignmentType.LEFT,
            style: { paragraph: { indent: { left: 720, hanging: 200 } } } },
        ],
      },
      ...orderedRefs.map((reference) => ({
        reference,
        levels: [
          { level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
            style: { paragraph: { indent: { left: 400, hanging: 260 } } } },
          { level: 1, format: LevelFormat.LOWER_LETTER, text: "%2.", alignment: AlignmentType.LEFT,
            style: { paragraph: { indent: { left: 760, hanging: 260 } } } },
        ],
      })),
    ],
  },
  sections: [
    {
      properties: { page: { margin: { top: 1300, bottom: 1200, left: 1440, right: 1440 } } },
      footers: { default: footer("Kam Ki Lead — technical documentation") },
      children: [...cover, ...portrait],
    },
    {
      properties: {
        page: {
          size: { orientation: PageOrientation.LANDSCAPE },
          margin: { top: 1200, bottom: 1100, left: 936, right: 936 },
        },
      },
      footers: { default: footer("Kam Ki Lead — traceability matrix") },
      children: landscape,
    },
  ],
});

const buffer = await Packer.toBuffer(doc);
writeFileSync(OUT, buffer);
process.stdout.write(`${OUT}: ${(buffer.length / 1024 / 1024).toFixed(2)} MB, ` +
  `${portrait.length} portrait blocks, ${landscape.length} landscape blocks, ${diagram} diagrams\n`);
